/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean nvram_wr (UInt16 nvram_addr , const void * data_addr , UInt16 size)
{
  CRITICAL ;

  Boolean status = FALSE ;

  C_ENTER ;
    {
      nvram_cache_update () ;
    
      if (0 < size && size <= NVRAM_SIZE && nvram_addr < NVRAM_SIZE)
        {
          #define NVRAM_RAM_DATA ((UInt8 *) NVRAM_FLASH_BUFF + nvram_addr)
    
          memcpy (NVRAM_RAM_DATA , data_addr , size) ;
    
          #undef  NVRAM_RAM_DATA
    
          nvram_do_cache_save = TRUE ;
    
          status = TRUE ;
        }
    }
  C_LEAVE ;

  return status ;
}

